
import pandas as pd
import matplotlib.pyplot as plt
 
# Read both CSVs generated by test_mpc_comparison.cpp
qp = pd.read_csv("results_QP.csv")
lp = pd.read_csv("results_LP.csv")
 
fig, (ax1, ax2) = plt.subplots(2, 1, figsize=(10, 8), sharex=True)
 
# Plot states and setpoints 
ax1.plot(qp['k'], qp['x_r'], color='red', linestyle=':', label='Setpoint')
ax1.plot(qp['k'], qp['x0'], color='tab:blue', linestyle='--', label='QP x0')
ax1.plot(qp['k'], qp['x1'], color='tab:blue', linestyle='-', linewidth=2, label='QP x1')
ax1.plot(lp['k'], lp['x0'], color='tab:orange', linestyle='--', label='LP x0')
ax1.plot(lp['k'], lp['x1'], color='tab:orange', linestyle='-', linewidth=2, label='LP x1')
ax1.set_ylabel('State Values')
ax1.set_title('MPC System States over Time: QP vs LP')
ax1.legend()
ax1.grid(True)
 
# plot controls
ax2.step(qp['k'], qp['u'], where='post', color='tab:blue', label='QP u')
ax2.step(lp['k'], lp['u'], where='post', color='tab:orange', label='LP u')

ax2.axhline(y=25.0, color='red', linestyle=':', label='Max u')
ax2.axhline(y=-25.0, color='purple', linestyle=':', label='Min u')
ax2.set_xlabel('Time Step (k)')
ax2.set_ylabel('Control Effort')
ax2.legend()
ax2.grid(True)
 
plt.tight_layout()
plt.show()
 
